def is_Sub_Array(sub, main):
    # If sublist is empty, it's considered a sublist of any list
    if not sub:
        return True
    # If main list is empty and sublist is not, sublist cannot be in main
    if not main:
        return False
    # Iterate through main list to find starting point of sublist
    for i in range(len(main) - len(sub) + 1):
        # Check if slice of main matches sublist
        if main[i:i + len(sub)] == sub:
            return True
    return False
